function agentFlow() {
  return `<div class="agent-workflow">${roles().map((r,i)=>{
    const status = state.replay ? (i < state.step ? 'done' : i === state.step ? 'active' : 'pending') : (i === 3 && state.paymentIncluded === null ? 'waiting':'done');
    const label = status === 'active' ? t('চলছে…','Working…') : status === 'done' ? t('সম্পন্ন','Complete') : status === 'waiting' ? t('উত্তর দরকার','Needs input') : t('অপেক্ষায়','Queued');
    return `<div class="agent-node ${status}" data-role="${r.id}"><button class="agent-symbol" data-action="agent-detail" data-role="${r.id}" aria-label="${t(r.bn,r.en)} · ${label}">${icon(r.ico)}</button><span class="node-name">${t(r.bn,r.en)}</span><span class="node-status">${status === 'active'?'<span class="event-spinner" style="width:9px;height:9px"></span>':''}${label}</span></div>`;
  }).join('')}</div>`;
}
function chartSvg(series, labels, {height=176, reserve=null, selected=-1, kind='flow'}={}) {
  const width=window.innerWidth<=600?360:660, left=44, right=16, top=18, bottom=27;
  const all=series.flatMap(s=>s.values); const max=Math.max(...all, reserve || 0)*1.16; const min=Math.min(0,...all)*1.2;
  const y = value => top + (max-value)/(max-min || 1)*(height-top-bottom);
  const x = index => left + index*(width-left-right)/(labels.length-1);
  const ticks=4;
  const grid=Array.from({length:ticks},(_,i)=>{const value=min+(max-min)*(i/(ticks-1));return `<line class="chart-grid" x1="${left}" y1="${y(value)}" x2="${width-right}" y2="${y(value)}"/><text x="${left-10}" y="${y(value)+3}" text-anchor="end">${Math.round(value/100000)}k</text>`;}).join('');
  const area=kind==='flow' ? `<defs><linearGradient id="flow-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b9cb94" stop-opacity=".42"/><stop offset="1" stop-color="#b9cb94" stop-opacity="0"/></linearGradient></defs><path d="M${x(0)},${y(0)} ${series[0].values.map((v,i)=>`L${x(i)},${y(v)}`).join(' ')} L${x(labels.length-1)},${y(0)} Z" fill="url(#flow-fill)"/>` : '';
  const lines=series.map((s,si)=>`<polyline points="${s.values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}" class="chart-line ${si===0&&kind==='runway'?'secondary':si>0&&kind==='flow'?'secondary':''}"/>`).join('');
  const circles=series[series.length-1].values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="${selected===i?5:3}" class="chart-focus"/><circle cx="${x(i)}" cy="${y(v)}" r="14" fill="transparent" tabindex="0" role="button" data-action="chart-point" data-kind="${kind}" data-index="${i}" aria-label="${escape(labels[i]+': '+money(v))}"><title>${escape(labels[i]+': '+money(v))}</title></circle>`).join('');
  const reserveLine=reserve===null?'':`<line x1="${left}" y1="${y(reserve)}" x2="${width-right}" y2="${y(reserve)}" stroke="#ba9b63" stroke-dasharray="3 5"/><text x="${width-right}" y="${y(reserve)-7}" text-anchor="end">${t('রিজার্ভ','Reserve')} ${money(reserve)}</text>`;
  const xlabel=labels.map((label,i)=>`<text class="${state.lang==='bn'?'bn':''}" x="${x(i)}" y="${height-5}" text-anchor="middle">${escape(label)}</text>`).join('');
  return `<svg viewBox="0 0 ${width} ${height}" class="chart ${kind==='flow'?'flow-chart':'runway-chart'}" role="group" aria-label="${t('ইন্টারঅ্যাকটিভ হিসাবের চার্ট। নিচে একই তথ্যের টেবিল আছে।','Interactive financial chart. The same data is available in the table below.')}" preserveAspectRatio="none">${grid}${area}${reserveLine}${lines}${circles}${xlabel}</svg>`;
}
