function buyingPage(){
  const selected=OFFERS.find(o=>o.id===state.offer),total=quoteTotal(selected.id,state.quantity),minimum=Math.min(...OFFERS.map(o=>quoteTotal(o.id,state.quantity))),impact=scenario(total);
  return `${heading('PURCHASING / QUOTE COMPARISON',t('ক্রয় প্রস্তাবের তুলনা','Compare purchase proposals'),t('একই পণ্য, একই unit। মোট খরচ ও শর্ত আলাদা করে দেখুন।','Same product, same unit. Compare total cost and recorded terms.'),button('quote-sources',t('Source quotation','Source quotations'),'file','compact'))}${demoNote()}<section class="buying-summary"><div class="product-identity"><div class="grain-art">${icon('leaf')}</div><div><h2>${t('মিনিকেট চাল · ২৫ কেজি','Miniket rice · 25 kg')}</h2><p class="meta muted">SKU RICE-025 · ${t('প্রতি বস্তার হিসাবে তুলনা','Normalized per bag')}</p></div></div><label class="quantity-field" for="quantity">${t('Quantity','Quantity')}<input id="quantity" type="number" min="1" max="100" step="1" value="${state.quantity}"><span>${t('বস্তা','bags')}</span></label></section><div class="offers-grid quote-workbench"><div class="quote-main"><section class="quote-comparison"><div class="queue-heading"><h2>${t('প্রাপ্ত quotation','Supplier quotations')}</h2><span>${n(3)} ${t('টি source','sources')}</span></div><div class="table-wrap"><table class="quote-table"><thead><tr><th><span class="sr-only">${t('নির্বাচন','Select')}</span></th><th>${t('Supplier','Supplier')}</th><th>${t('প্রতি বস্তা','Per bag')}</th><th>${t('Delivery','Delivery')}</th><th>${t('মোট','Total')}</th><th>${t('শর্ত','Terms')}</th></tr></thead><tbody>${OFFERS.map(o=>`<tr class="${o.id===state.offer?'selected':''}"><td><input id="offer-${o.id}" type="radio" class="offer-select" name="offer" value="${o.id}" ${o.id===state.offer?'checked':''} aria-label="${t(o.bn,o.en)}"></td><td><label for="offer-${o.id}"><strong>${t(o.bn,o.en)}</strong><small>${o.ref} · SAMPLE</small></label></td><td class="money">${money(o.unitPaisa)}</td><td class="money">${money(o.shippingPaisa)}</td><td><strong class="money">${money(quoteTotal(o.id,state.quantity))}</strong>${quoteTotal(o.id,state.quantity)===minimum?`<small class="quote-lowest">${t('কম মোট খরচ','Lowest total')}</small>`:''}</td><td>${badge(o.verified?t('শর্ত স্পষ্ট','Recorded'):t('প্রশ্ন বাকি','Needs input'),o.verified?'':'warning')}</td></tr>`).join('')}</tbody></table></div></section><section class="quote-source-panel"><div class="section-head"><div class="flex">${icon('file')}<h2>${t('নির্বাচিত source-এর শর্ত','Selected source terms')}</h2><span class="meta muted">${selected.ref}</span></div><div class="quote-source-text"><span>${t('মূল quotation-এর বক্তব্য · synthetic','Original quote statement · synthetic')}</span><p>${t(selected.termBn,selected.termEn)}</p><div>${money(selected.unitPaisa)} × ${n(state.quantity)} + ${money(selected.shippingPaisa)} ${t('ডেলিভারি','delivery')} = <strong>${money(total)}</strong></div></div>${quiet('quote-source',t('পুরো source পড়ুন','Read full source'),'link',`data-offer="${selected.id}"`)}</section><section class="quote-agent-review"><div class="console-heading"><span class="console-mark">${icon('search')}</span><div><h2>Terms specialist</h2><p>${t('অস্পষ্ট শর্ত ও হিসাবের ভিত্তি','Ambiguous terms and calculation basis')}</p></div></div><div class="quote-review-body"><div class="review-findings"><div>${icon('check')}<p>${t('তিনটি quotation একই ২৫ কেজির unit-এ তুলনা করা হয়েছে।','All three quotations use the same 25 kg unit.')}</p></div><div>${icon('check')}<p>${t('Delivery মোট খরচে অন্তর্ভুক্ত।','Delivery is included in total cost.')}</p></div><div class="finding-unknown">${icon('help')}<p>${t('শাপলার “৬+১” অফারের যোগ্যতা অজানা। তাই bonus ধরে সাশ্রয় দেখানো হয়নি।','Eligibility for Shapla’s “6+1” offer is unknown. No bonus-based saving is assumed.')}</p></div></div><p class="case-footnote">${t('এই review predefined fixture-এর। Unit cost calculation deterministic; live model inference নয়।','This review uses predefined fixtures. Unit-cost calculation is deterministic; no live model inference.')}</p></div></section></div><aside class="decision-tray quote-decision"><h2>${t('নির্বাচিত প্রস্তাব','Selected proposal')}</h2><p class="meta muted mt16">${t(selected.bn,selected.en)} · ${n(state.quantity)} ${t('বস্তা','bags')}</p><div class="tray-total">${money(total)}</div><div class="quote-money-row"><span>${t('হাতে আছে','Available')}</span><strong class="money">${money(AVAILABLE_PAISA)}</strong></div><div class="quote-money-row"><span>${t('এখন কিনলে থাকবে','After this purchase')}</span><strong class="money">${money(AVAILABLE_PAISA-total)}</strong></div><div class="impact-strip ${impact.firstReserveBreach>=0?'warning':''}">${icon('calendar')}<div><h3>${impact.firstReserveBreach>=0?t('পরের দিনের reserve দেখুন','Check future reserve'):t('নমুনায় reserve অক্ষুণ্ণ','Reserve retained in sample')}</h3><p>${t('বর্তমান funds আর ভবিষ্যৎ affordability এক নয়।','Current funds and future affordability differ.')}</p></div></div>${button('buying-impact',t('Cash impact খুলুন','Open cash impact'),'graph','compact')}${button('draft-order',t('Order draft review','Review order draft'),'file','primary',total>AVAILABLE_PAISA?'disabled':'')}<p class="case-footnote">${t('Draft-এর পরে review। Supplier message, payment বা stock receipt নিজে থেকে হয় না।','Review follows the draft. No supplier message, payment or stock receipt is automatic.')}</p></aside></div>`;
}
function casePage() {
  if(!['supplier','cash','offer'].includes(state.activeScenario))return exceptionPage();
  const rec=reconcile(state.paymentIncluded);
  return `${heading('CASE-024 / RAHMAN TRADERS',t('একটি payment। দুটি সম্ভাব্য হিসাব।','One payment. Two possible balances.'),t('তিনটি source থেকে প্রয়োজনীয় প্রশ্ন, তারপর review।','Three sources, a missing fact, then your review.'),button('replay',state.replay?t('ধাপ চলছে','Running example'):t('Agent-এর ধাপ দেখুন','Run the workflow'),'play','primary compact',state.replay?'disabled':'')+quiet('reset-case',t('Reset','Reset'),'refresh'))}<div class="case-status-line">${badge(rec.blocker?t('উত্তরের অপেক্ষায়','Waiting for your answer'):t('Review-এর জন্য','Ready for review'),rec.blocker?'warning':'') }<span>${t('Synthetic sources · version ','Synthetic sources · version ')+n(state.caseVersion)}</span><span>${t('কোনো posting হয়নি','No posting has occurred')}</span></div><div class="evidence-workbench"><nav class="evidence-nav" aria-label="${t('এই case-এর sources','Sources in this case')}"><h2>${t('Source documents','Source documents')}</h2>${[['bill','INV-025',t('Supplier-এর দাবি','Supplier statement')],['payment','PAY-004',t('Payment রসিদ','Payment receipt')],['return','RETURN-003',t('ফেরতের স্বীকৃতি','Return acknowledgement')]].map(([id,ref,title])=>`<button data-action="select-source" data-source="${id}" aria-pressed="${state.source===id}" class="document-tab ${state.source===id?'selected':''}">${icon('file')}<span><strong>${title}</strong><small>${ref}</small></span>${id==='payment'?'<span class="source-question">?</span>':''}</button>`).join('')}<div class="evidence-policy">${icon('shield')}<p>${t('রসিদ থাকা, প্রযোজ্য হওয়া ও আগে বাদ থাকা—তিনটি আলাদা তথ্য।','Receipt existence, applicability and prior inclusion are separate facts.')}</p></div></nav><div class="document-stage">${sourceDocument()}<div id="evidence-trace" class="sr-only">${sourceSummary(state.source)} ${quiet('source',t('Source খুলুন','Open source'),'file',`data-source="${state.source}"`)}</div></div><aside class="case-review-pane"><div class="review-pane-head">${icon('layers')}<strong>${t('সংগতির review','Shongoti review')}</strong>${badge(t('নমুনা','Sample'),'outline')}</div><div class="review-findings"><div>${icon('check')}<p>${t('৩,০০০ টাকার ফেরত গৃহীত; বর্তমান দাবিতে আগে বাদ নেই।','৳3,000 return accepted; not previously deducted.')}</p></div><div>${icon('check')}<p>${t('৪,০০০ টাকার payment এই supplier-এর জন্য প্রযোজ্য।','The ৳4,000 payment applies to this supplier.')}</p></div><div class="finding-unknown">${icon('help')}<p>${t('Payment বর্তমান দাবিতে আগে বাদ আছে কি না অজানা।','Prior payment inclusion remains unknown.')}</p></div></div><section class="inline-question"><h2>${t('Payment কি আগেই বাদ আছে?','Is the payment already included?')}</h2><p>${t('এই উত্তরে বদলাবে কত টাকা আবার বাদ যাবে।','This determines whether another deduction is appropriate.')}</p><div class="answer-options">${button('answer',t('হ্যাঁ, আছে','Yes, included'),'','compact',`id="answer-included" data-answer="included" aria-pressed="${state.paymentIncluded===true}" ${state.replay?'disabled':''}`)}${button('answer',t('না, নেই','No, not yet'),'','compact',`id="answer-not-included" data-answer="not-included" aria-pressed="${state.paymentIncluded===false}" ${state.replay?'disabled':''}`)}${quiet('answer',t('জানি না','Still unknown'),'','data-answer="unknown" id="answer-unknown"')}</div></section><div class="case-decision">${rec.duePaisa===null||state.replay?`<div class="alternative"><span>${t('আগে বাদ থাকলে','If included')}</span><strong class="money">${money(2200000)}</strong></div><div class="alternative"><span>${t('বাদ না থাকলে','If not included')}</span><strong class="money">${money(1800000)}</strong></div>`:`<span class="label">${t('নির্বাচিত তথ্য অনুযায়ী প্রদেয়','Payable using the selected facts')}</span><div class="due-result money">${money(rec.duePaisa)}</div>`}</div>${confidence(rec)}${button('review-case',t('খসড়া review করুন','Review draft'),'shield','primary',rec.duePaisa===null||state.replay?'disabled':'')}<p class="case-footnote">${t('এখানে উত্তর দেওয়া synthetic clarification। বাস্তব অনুমোদন বা payment নয়।','Selections are synthetic clarifications, not real approvals or payments.')}</p></aside></div><section class="case-run-panel"><div class="section-head"><div><h2>${t('Agent-এর কাজের trail','Agent work trail')}</h2><p class="meta muted">${t('কাজের ফল, tool ও source—private reasoning নয়।','Task outcomes, tools and sources; no private reasoning.')}</p></div>${state.replay?quiet('pause-replay',state.paused?t('চালান','Resume'):t('Pause','Pause'),state.paused?'play':'pause'):badge(t('নমুনা run','Example run'),'outline')}</div>${agentFlow()}<ol class="event-list">${state.events.map((e,i)=>`<li><time>09:4${i+1}</time>${icon('check')}<span>${t(e.bn,e.en)}</span><span class="event-source">${e.source}</span></li>`).join('')}</ol></section>`;
}
function exceptionPage() {
  const selected=scenarios().find(s=>s.id===state.activeScenario)||scenarios()[3];
  const receiving=selected.id==='receiving',duplicate=selected.id==='duplicate';
  const facts=receiving?[[t('Order-এ ছিল','Ordered'),'10 bags'],[t('পাওয়া গেছে','Received'),'8 bags'],[t('নষ্ট হয়েছে','Damaged'),'1 bag'],[t('Usable stock','Usable stock'),'7 bags']]:duplicate?[[t('Payment reference','Payment reference'),'TXN-009'],[t('প্রথম action','First action'),'POSTED'],[t('দ্বিতীয় request','Second request'),'SAME IDEMPOTENCY KEY'],[t('দ্বিতীয় posting','Second posting'),'BLOCKED']]:[[t('Source','Source'),'NOTICE-006'],[t('Document date','Document date'),'Not confirmed'],[t('Jurisdiction','Jurisdiction'),'Not established'],[t('নির্ভরযোগ্য deadline','Supported deadline'),'Unknown']];
  return `${heading(selected.ref+' / JUDGE SCENARIO',selected.title,selected.sub,button('open-scenarios',t('অন্য scenario','Other scenarios'),'layers','compact'))}<div class="case-status-line">${badge(selected.status,duplicate?'danger':'warning')}<span>${t('Predefined synthetic case · বাইরে কোনো action যায় না','Predefined synthetic case · no external actions')}</span></div><div class="exception-layout"><section class="exception-source"><div class="document-toolbar">${icon('file')}<strong>${t('Source facts','Source facts')}</strong><span>${selected.ref}</span></div><div class="exception-paper"><h2>${receiving?'DELIVERY / COUNT SHEET':duplicate?'PAYMENT EXECUTION RECORD':'NOTICE REVIEW'}</h2><p class="meta muted">SYNTHETIC DOCUMENT</p>${facts.map(([label,value])=>`<div class="exception-fact"><span>${label}</span><strong>${value}</strong></div>`).join('')}<div class="evidence-trace">${icon('link')}<p>${receiving?t('Shortage ২ + damaged ১ = claim-এর সম্ভাব্য quantity ৩। Supplier acceptance ছাড়া এটি payable থেকে বাদ যায় না।','Shortage 2 + damaged 1 = 3 units potentially claimable. This cannot reduce payable without supplier acceptance.'):duplicate?t('একই reference-এর দ্বিতীয় request-এর কারণে নতুন financial entry তৈরি হয় না।','The second request with the same reference creates no new financial entry.'):t('Document দেখে একটি নিশ্চিত legal deadline বানানো যাবে না। প্রযোজ্য official source ও তারিখ দরকার।','A document cannot justify inventing a binding legal deadline. Applicable official source and date are required.')}</p></div></div></section><section class="exception-review"><h2>${t('কাজ থেকে সিদ্ধান্ত','From work to decision')}</h2><ol class="exception-steps"><li>${icon('file')}<div><strong>${t('Document specialist','Document specialist')}</strong><p>${t('Source-এর প্রতিষ্ঠিত facts আলাদা করে','Separates established source facts')}</p></div></li><li>${icon('graph')}<div><strong>${receiving?'Receiving tool':duplicate?'Idempotency guard':'Source review'}</strong><p>${receiving?t('শুধু ৭টি usable bag; credit এখনও pending','Only 7 usable bags; credit remains pending'):duplicate?t('আগের reference পেয়ে দ্বিতীয় posting আটকায়','Finds the prior reference and blocks a second posting'):t('তারিখ ও applicability অজানা রেখেছে','Leaves date and applicability unknown')}</p></div></li><li>${icon('shield')}<div><strong>Skeptic</strong><p>${receiving?t('Pending credit দিয়ে supplier due কমানো বন্ধ','Prevents pending credit from reducing the supplier due'):duplicate?t('নতুন posting শূন্য; টাকা দুবার যায়নি','Zero new postings; no second payment'):t('আরও source ছাড়া নিশ্চিত পরামর্শ নয়','No definite guidance without further sources')}</p></div></li></ol><div class="console-question"><strong>${t('আপনার জন্য next step','Your next step')}</strong><p>${receiving?t('শারীরিক count review করে supplier-এর স্বীকৃতি সংগ্রহ করুন।','Review physical counts and obtain supplier acknowledgement.'):duplicate?t('দ্বিতীয়বার payment না করে আগের receipt দেখুন।','Inspect the original receipt rather than paying again.'):t('পূর্ণ notice, issuing authority ও বর্তমান official reference যোগ করুন।','Add the full notice, issuing authority and current official reference.')}</p>${button('exception-review',t('ফল ও সীমা দেখুন','Inspect result and limits'),'file','primary compact')}</div><p class="case-footnote">${t('এটি predefined design scenario। Production receiving, payment বা legal integration নয়।','A predefined design scenario, not a production receiving, payment or legal integration.')}</p></section></div>`;
}
function scenarioPage(){return `${heading('JUDGE WORKSPACE / SCENARIO LIBRARY',t('নিজে করে দেখুন। কোথাও আটকে যাবেন না।','Explore the decisions, not empty screens.'),t('প্রতিটি scenario-তে source, অজানা তথ্য, agent-এর কাজ ও ফল আগে থেকে সাজানো আছে।','Each scenario includes sources, unknowns, agent work and a reviewable outcome.'),button('reset-judge',t('Fresh session শুরু করুন','Start a fresh session'),'refresh','primary compact'))}<div class="scenario-library">${scenarios().map((s,i)=>`<article class="scenario-entry"><div class="scenario-entry-top"><span class="eyebrow">${s.ref}</span>${badge(s.status,s.type==='blocked'?'danger':s.type==='question'?'warning':'')}</div><h2>${s.title}</h2><p>${s.sub}</p><div class="scenario-coverage">${icon('layers')}${s.agent}</div>${button('scenario',t('Scenario explore করুন','Explore scenario'),'','primary compact',`data-scenario="${s.id}"`)}</article>`).join('')}</div><section class="judge-capabilities"><h2>${t('আরও যা explore করতে পারবেন','Also available to explore')}</h2><div>${button('copilot',t('Contextual Copilot','Contextual Copilot'),'spark')}${button('inbox',t('Actionable inbox','Actionable inbox'),'bell')}${button('speak',t('Voice brief','Voice brief'),'audio')}${button('motion',t('Reduced motion','Reduced motion'),'settings')}</div><p>${t('সব scenario synthetic। Tools ও chat-এর mode দৃশ্যমান; live model বা external delivery claim নেই। Voice device support-এর ওপর নির্ভরশীল।','All scenarios are synthetic. Tool/chat modes are visible; no live model or external delivery is claimed. Voice depends on device support.')}</p></section>`;}
function authPage(register=false) {
  return `<div class="auth-shell"><section class="auth-story"><a class="auth-brand" href="#/login">${logo}<span>সংগতি<small>SHONGOTI</small></span></a><div class="auth-story-main"><span class="eyebrow">YOUR SHOP. IN SYNC.</span><h1>${t('প্রতিটি হিসাবের পেছনে<br>একটা পরিষ্কার গল্প।','A clearer story<br>behind every number.')}</h1><p>${t('দোকানের কাজ, প্রমাণ আর সিদ্ধান্তকে একসঙ্গে রাখুন।','Bring your shop’s work, evidence and decisions together.')}</p><div class="auth-work-note"><div class="auth-note-head">${icon('layers')}<strong>${t('সংগতি খুঁজে পেয়েছে','Shongoti found a question')}</strong><span>CASE-024</span></div><p>${t('রসিদ আছে। কিন্তু payment আগেই বাদ আছে কি না অজানা।','The receipt exists. Whether the payment was already included is still unknown.')}</p><div class="auth-evidence-chain"><span>INV-025</span><i></i><span>PAY-004</span><i></i><strong>?</strong></div><div class="auth-note-foot">${icon('shield')}${t('অনুমানের আগে প্রমাণ। Action-এর আগে আপনার review।','Evidence before assumptions. Your review before action.')}</div></div></div><p class="auth-story-footer">${t('বাংলায় সহজ। সিদ্ধান্তে স্বচ্ছ।','Bangla-first. Clear at every decision.')}</p></section><section class="auth-form-side"><div class="auth-top-actions">${quiet('language',state.lang==='bn'?'English':'বাংলা')}${badge(t('Local design build','Local design build'),'outline')}</div><div class="auth-form-wrap"><h2>${register?t('আপনার দোকানের workspace খুলুন','Create your shop workspace'):t('আবার স্বাগতম','Welcome back')}</h2><p class="auth-description">${register?t('একটি নতুন, আলাদা account তৈরি হবে। Demo-এর টাকা আপনার account-এ যোগ হবে না।','Create a separate account. Demo finances never appear in your account.'):t('আপনার local account-এ ঢুকুন অথবা নিচে judge workspace explore করুন।','Sign in to your local account, or explore the judge workspace below.')}</p><form id="auth-form" data-mode="${register?'register':'login'}">${register?`<label for="owner-name">${t('আপনার নাম','Your name')}</label><input id="owner-name" name="name" autocomplete="name" minlength="2" maxlength="80" required><label for="shop-name">${t('দোকানের নাম','Shop name')}</label><input id="shop-name" name="shopName" autocomplete="organization" minlength="2" maxlength="100" required>`:''}<label for="auth-phone">${t('মোবাইল নম্বর','Mobile number')}</label><input id="auth-phone" name="phone" type="tel" autocomplete="tel-national" placeholder="017XXXXXXXX" maxlength="18" required><label for="auth-password">${t('Password','Password')}</label><div class="password-field"><input id="auth-password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?'12':'1'}" maxlength="128" required><button type="button" data-action="show-password">${t('দেখুন','Show')}</button></div>${register?`<p class="field-hint">${t('অন্তত ১২ অক্ষর। Phone ownership এখনও যাচাই হয়নি; SMS পাঠানো হয় না।','At least 12 characters. Phone ownership is unverified; no SMS is sent.')}</p>`:''}<p class="auth-error" id="auth-error" role="alert">${escape(state.authError)}</p><button type="submit" class="button primary auth-submit">${register?t('Account তৈরি করুন','Create account'):t('লগইন করুন','Sign in')}</button></form><p class="auth-switch">${register?t('আগে account আছে?','Already have an account?'):t('নতুন শুরু করছেন?','New to Shongoti?')} <a href="#/${register?'login':'register'}">${register?t('লগইন করুন','Sign in'):t('Account খুলুন','Create account')}</a></p><div class="auth-divider"><span>${t('বিচারক বা reviewer?','Judging or reviewing?')}</span></div><button class="judge-entry" data-action="judge-login"><span class="judge-entry-icon">${icon('play')}</span><span><strong>${t('এক ক্লিকে Judge workspace','Open judge workspace in one click')}</strong><small>${t('Password ছাড়াই · ৬টি predefined scenario · reset করা যায়','No password · 6 predefined scenarios · reset anytime')}</small></span></button><p class="auth-local-note">${t('Server-verified local account ও HttpOnly session। মূল production authentication-এর সঙ্গে এখনও merge করা হয়নি।','Server-verified local accounts and HttpOnly sessions. Not yet merged into production authentication.')}</p></div></section></div>`;
}
function accountHome(){return `${heading('YOUR ACCOUNT',t('Workspace তৈরি হয়েছে।','Your workspace is ready.'),escape(state.session?.shopName||''),button('logout',t('লগআউট','Sign out'),'','compact'))}<section class="new-account-state">${icon('bag')}<h2>${t('এখানে আপনার নিজের হিসাব আসবে।','Your own business records belong here.')}</h2><p>${t('এই local design build-এ merchant ledger service সংযুক্ত নেই। তাই demo balance, invoice বা agent ফল আপনার account হিসেবে দেখানো হচ্ছে না।','The merchant ledger service is not connected in this local design build. Demo balances, invoices and agent results are not presented as your records.')}</p><div>${button('judge-login',t('নমুনা scenario explore করুন','Explore sample scenarios'),'play','primary')}${button('logout',t('লগআউট','Sign out'),'','compact')}</div><p class="meta muted">${t('Phone ownership যাচাই হয়নি। Password reset / SMS sender এই local build-এ নেই।','Phone ownership is unverified. Password recovery / SMS delivery are not configured in this local build.')}</p></section>`;}
async function authRequest(mode,data={}) {
  const response=await fetch('/preview-api/auth/'+mode,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
  const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;
}
async function enterJudge(el){
  if(state.authBusy)return;state.authBusy=true;el.disabled=true;const label=el.innerHTML;el.innerHTML=`<span class="event-spinner"></span> ${t('Workspace খোলা হচ্ছে…','Opening workspace…')}`;
  try{const result=await authRequest('judge');state.session=result.user;state.authError='';state.activeScenario='supplier';state.paymentIncluded=null;state.expense=800000;state.promise=false;state.offer='rahman';state.quantity=6;state.caseVersion=1;state.chat=[];state.chatBusy=false;state.source='bill';state.workFilter='all';state.saved=false;state.paused=false;clearTimeout(chatTimer);state.events=[...REPLAY_STEPS];state.replay=false;clearTimeout(replayTimer);closeOverlay();state.page='dashboard';location.hash='/dashboard';render(true);}
  catch(error){el.disabled=false;el.innerHTML=label;const field=$('#auth-error');if(field)field.textContent=error.message;else toast(error.message);}
  finally{state.authBusy=false;}
}
async function bootstrap(){try{const response=await fetch('/preview-api/auth/session',{credentials:'same-origin'});if(!response.ok)throw new Error('Session service unavailable');state.session=(await response.json()).user;}catch{state.authError=t('Local account service পাওয়া যায়নি। Preview server-এর নতুন version চালু করুন।','Local account service is unavailable. Start the updated preview server.');}finally{state.authLoading=false;if(!state.session&&!['login','register'].includes(state.page))state.page='login';render(true);window.dispatchEvent(new Event('preview-ready'));}}

function render(animate=false) {
  const active=document.activeElement?.id, start=document.activeElement?.selectionStart;
  document.documentElement.lang=state.lang;
  $('#app').dataset.mode=state.session?.kind||'anonymous';
  document.body.classList.toggle('motion-off',state.motion==='off');
  document.title=`${pageNames()[state.page]} · ${t('সংগতি','Shongoti')} · Design preview`;
  if(state.authLoading){$('#app').innerHTML='<div class="session-loading"><span class="event-spinner"></span><p>'+t('Session যাচাই হচ্ছে…','Checking your session…')+'</p></div>';return;}
  if(!state.session||['login','register'].includes(state.page)){$('#app').innerHTML=authPage(state.page==='register');return;}
  const pages={dashboard,case:casePage,buying:buyingPage,planner:plannerPage,scenarios:scenarioPage};
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="${t('প্রধান মেনু','Main navigation')}"><a class="brand" href="#/dashboard" aria-label="${t('সংগতি · আজকের দোকান','Shongoti · Today')}">${logo}<span class="brand-name">সংগতি<small>SHONGOTI</small></span></a><div class="workspace-name">${t('আপনার কাজের টেবিল','YOUR WORKSPACE')}</div><nav class="nav-links">${['dashboard','case','buying','planner'].map((id,i)=>`<a class="nav-link ${state.page===id?'active':''}" href="#/${id}" ${state.page===id?'aria-current="page"':''} title="${pageNames()[id]}">${icon(['home','layers','bag','graph'][i])}<span class="nav-label">${pageNames()[id]}</span><span class="nav-index">0${i+1}</span></a>`).join('')}</nav><div class="sidebar-note"><div class="eyebrow">A LITTLE MORE IN SYNC</div><p>${t('দোকান আপনার। হিসাবের পাশে সংগতি।','Your shop. A little more in sync.')}</p>${badge(t('৪টি screen-এর preview','4-screen preview'),'dark')}</div><div class="sidebar-spacer"></div><div class="sidebar-bottom">${quiet('motion',state.motion==='off'?t('Motion বন্ধ আছে','Motion is off'):t('Motion কমিয়ে দিন','Reduce motion'),'settings')}${quiet('about',t('এই preview সম্পর্কে','About this preview'),'help')}<div class="profile"><span class="avatar">মী</span><span class="profile-text">${t('মীনা স্টোর','Meena Store')}<small>${t('উদাহরণের দোকান','Example shop')}</small></span></div></div></aside><div class="workarea"><header class="topbar"><div class="breadcrumb"><span>${t('দোকানের খাতা','Workspace')}</span><strong>${pageNames()[state.page]}</strong><span class="preview-label">DESIGN PREVIEW</span></div><div class="top-actions"><button class="top-search" data-action="search">${icon('search')}${t('খুঁজুন','Find something')}<kbd>/</kbd></button><button class="lang-button" data-action="language" aria-label="${t('Switch to English','বাংলায় দেখুন')}">${t('EN','বাংলা')}</button><button class="icon-button" data-action="inbox" aria-label="${t('নমুনা notification','Sample notifications')}">${icon('bell')}<span class="notification-count">3</span></button>${button('copilot',t('সংগতিকে বলুন','Ask Shongoti'),'spark','compact')}</div></header><main class="content ${animate?'page-enter':''}" id="main" tabindex="-1">${pages[state.page]()}<footer class="footer-note"><span>${t('সিদ্ধান্ত আপনার। প্রমাণের পাশে সংগতি।','Your decisions. Supported by evidence.')}</span><span>LOCAL DESIGN STUDY · 23 NOV 2026</span></footer></main></div></div>`;
  const nav=$('.nav-links');if(nav)nav.insertAdjacentHTML('beforeend',`<a class="nav-link ${state.page==='scenarios'?'active':''}" href="#/scenarios" ${state.page==='scenarios'?'aria-current="page"':''}>${icon('play')}<span class="nav-label">${t('Judge scenarios','Judge scenarios')}</span></a>`);
  const modeLabel=$('.preview-label');if(modeLabel)modeLabel.textContent=state.session.kind==='judge'?'JUDGE DEMO':'LOCAL ACCOUNT';
  if(state.page==='dashboard'){
    const items=scenarios(),questionCount=items.filter(s=>s.type==='question').length;
    const metric=$('.metrics-strip>div:last-child strong');if(metric)metric.innerHTML=`${n(questionCount)} <span class="metric-word">${t('টি কাজ','items')}</span>`;
    document.querySelectorAll('.work-tabs button').forEach(tab=>{tab.querySelector('small').textContent=tab.dataset.filter==='all'?items.length:items.filter(s=>s.type===tab.dataset.filter).length;});
    if(state.paymentIncluded!==null&&!state.replay){const panel=$('.agent-console');panel.querySelector('.console-mode .badge').textContent=t('Review-এর জন্য প্রস্তুত','Ready for owner review');panel.querySelector('.console-question>strong').textContent=t('আপনার review দরকার','Your review is needed');panel.querySelector('.console-question>p').textContent=t('নির্বাচিত তথ্য অনুযায়ী প্রদেয় ','Payable using the selected facts: ')+money(reconcile(state.paymentIncluded).duePaisa);panel.querySelectorAll('.console-task p')[2].textContent=t('একটি সমর্থিত বিকল্প: ','One supported alternative: ')+money(reconcile(state.paymentIncluded).duePaisa);panel.querySelectorAll('.console-task p')[3].textContent=t('Critical প্রশ্নের উত্তর পাওয়া গেছে। Owner approval এখনও বাকি।','Critical fact clarified. Owner approval remains outstanding.');}
  }
  const profile=$('.profile');if(profile){profile.innerHTML=`<span class="avatar">${state.session.kind==='judge'?'J':escape(state.session.name.slice(0,1))}</span><span class="profile-text">${escape(state.session.shopName)}<small>${state.session.kind==='judge'?t('Judge session','Judge session'):t('আপনার account','Your account')}</small></span><button class="profile-logout" data-action="logout" aria-label="${t('লগআউট','Sign out')}">${icon('close')}</button>`;}
  const note=$('.sidebar-note');if(note)note.innerHTML=`<div class="eyebrow">${state.session.kind==='judge'?'JUDGE WORKSPACE':'YOUR WORKSPACE'}</div><p>${state.session.kind==='judge'?t('৬টি scenario প্রস্তুত। নতুন data দরকার নেই।','6 scenarios ready. No setup needed.'):t('নিজের account · demo data নয়।','Your account · no demo data.')}</p>${quiet(state.session.kind==='judge'?'open-scenarios':'judge-login',t('Scenario library','Scenario library'),'layers')}`;
  if(state.session.kind!=='judge')$('#main').innerHTML=accountHome();
  if(active && document.getElementById(active)) { const target=document.getElementById(active); target.focus({preventScroll:true});if(typeof start==='number')try{target.setSelectionRange(start,start);}catch{} }
}
let toastTimer, replayTimer, chatTimer, refreshTimer, previousFocus, overlayType=null;
function toast(message) { $('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200); }
function navigate(page) { closeOverlay();if(state.page===page){render();return;}location.hash='/'+page; }
function closeOverlay() { if(!overlayType)return;$('#overlay-root').innerHTML='';overlayType=null;$('#app').inert=false;document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true}); }
function modal(title,body,{wide=false}={}) {
  if(!overlayType)previousFocus=document.activeElement;overlayType='dialog';$('#app').inert=true;document.body.style.overflow='hidden';
  $('#overlay-root').innerHTML=`<div class="overlay-backdrop" data-backdrop="true"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" ${wide?'style="width:min(100%,720px)"':''}><button class="icon-button dialog-close" data-action="close" aria-label="${t('বন্ধ করুন','Close')}">${icon('close')}</button><h2 id="dialog-title">${title}</h2>${body}</section></div>`;
  $('#overlay-root .dialog-close').focus();
}
function showSource(source) {
  const content={bill:[t('Supplier-এর বর্তমান দাবি','Supplier’s current demand'),'INV-025',t('২৩ নভেম্বরের খাতায় প্রদেয় হিসেবে ২৫,০০০ টাকা লেখা আছে। এই অঙ্কে আগের payment বাদ আছে কি না এখানে স্পষ্ট নয়।','The 23 November statement records ৳25,000 payable. It does not establish whether the prior payment was already deducted.')],payment:[t('৪,০০০ টাকার payment','The ৳4,000 payment'),'PAY-004',t('এই payment রহমান ট্রেডার্সের জন্য প্রযোজ্য। টাকা দেওয়া হয়েছিল—এটি প্রতিষ্ঠিত। বর্তমান ২৫,০০০-এর দাবি সেই payment-এর পরের অঙ্ক কি না, সেটি আলাদা প্রশ্ন।','This payment applies to Rahman Traders. Payment occurred; whether the current ৳25,000 demand already reflects it is a separate question.')],return:[t('ফেরত গ্রহণের স্বীকৃতি','Acknowledged return'),'RETURN-003',t('“৩,০০০ টাকার মাল ফেরত গ্রহণ করেছি। এটি বর্তমান ২৫,০০০ টাকার দাবিতে এখনও বাদ দেওয়া হয়নি।” এই বক্তব্যটি উদাহরণের প্রতিষ্ঠিত তথ্য।','“We accepted the ৳3,000 return. It has not yet been deducted from the current ৳25,000 demand.” This is an established fact in the synthetic example.')]};
  const [title,ref,text]=content[source]||content.bill;
  modal(title,`<p class="dialog-intro">${t('Synthetic source text · আসল রসিদ নয়','Synthetic source text · not a real receipt')}</p><div class="source-document"><strong>${ref}</strong><p>${text}</p></div><p class="source-reference">${ref} · CASE-024 · SYNTHETIC FIXTURE</p>${button('close',t('বুঝেছি','Got it'),'check','primary')}`);
}
function nextReplay() {
  if(!state.replay||state.paused)return;
  replayTimer=setTimeout(()=>{ state.events.push(REPLAY_STEPS[state.step]);state.step+=1;if(state.step>=REPLAY_STEPS.length){state.replay=false;state.paused=false;}render();if(state.replay)nextReplay();else toast(t('নমুনা যাচাই থেমেছে একটি জরুরি প্রশ্নে।','The example stops at a critical question.'));},1100);
}
function startReplay() { clearTimeout(replayTimer);state.replay=true;state.paused=false;state.step=0;state.events=[];state.paymentIncluded=null;state.caseVersion+=1;render();nextReplay(); }
const briefText = () => t('আজ বড় খরচের আগে বৃহস্পতিবারের হিসাব দেখুন। নমুনা হিসাবে আজ আট হাজার টাকা খরচ করলে বৃহস্পতিবার তিন হাজার টাকার রিজার্ভের নিচে নামবে। Supplier-এর আগের চার হাজার টাকার payment দাবিতে আগেই বাদ আছে কি না, সে তথ্যও দরকার।','Before a large purchase, check Thursday. In this example, spending eight thousand taka today puts Thursday below the three thousand taka reserve. We also need to know whether the supplier demand already includes the previous four thousand taka payment.');
function speakBrief() {
  if(!('speechSynthesis' in window)){toast(t('এই browser-এ voice নেই। Brief-এর লেখা screen-এ আছে।','Voice is unavailable here. The brief transcript remains on screen.'));return;}
  if(speechSynthesis.speaking){speechSynthesis.cancel();document.querySelectorAll('.brief-wave').forEach(e=>e.classList.remove('speaking'));return;}
  const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(state.lang==='bn'?'bn':'en'));
  if(!voice){toast(t('বাংলা voice পাওয়া যায়নি। লেখা brief-টি পড়ুন; অন্য ভাষায় স্বয়ংক্রিয়ভাবে পড়ছি না।','No matching English voice is available. Read the visible brief transcript.'));return;}
  const utterance=new SpeechSynthesisUtterance(briefText());utterance.voice=voice;utterance.lang=voice.lang;
  utterance.onstart=()=>document.querySelectorAll('.brief-wave').forEach(e=>e.classList.add('speaking'));
  utterance.onend=utterance.onerror=()=>document.querySelectorAll('.brief-wave').forEach(e=>e.classList.remove('speaking'));
  speechSynthesis.speak(utterance);
}
function openCopilot() {
  if(!overlayType)previousFocus=document.activeElement;
  overlayType='copilot';$('#app').inert=true;document.body.style.overflow='hidden';
  const messages=state.chat.length?state.chat.map(m=>`<div class="chat-message ${m.role}"><div class="chat-author">${m.role==='user'?t('আপনি','YOU'):'SHONGOTI · LOCAL EXAMPLE'}</div>${escape(m.text).replaceAll('\n','<br>')}${m.action?quiet(m.action,t('সংশ্লিষ্ট screen খুলুন','Open related screen'),'link'):''}</div>`).join(''):`<div class="chat-message assistant"><div class="chat-author">SHONGOTI · LOCAL EXAMPLE</div>${t('দোকানের কোন সিদ্ধান্তটা নিয়ে ভাবছেন? একটি উদাহরণ বেছে নিন।','What decision is on your mind? Try an example below.')}<div class="chat-suggestions">${button('chat-preset',t('আজ ৮,০০০ খরচ করলে কী হবে?','What if I spend ৳8,000 today?'),'graph','','data-prompt="scenario"')}${button('chat-preset',t('Supplier-এর কত টাকা পাওনা?','How much do we owe the supplier?'),'file','','data-prompt="case"')}${button('chat-preset',t('হাতে কত টাকা আছে?','How much money is available?'),'wallet','','data-prompt="balance"')}</div></div>`;
  $('#overlay-root').innerHTML=`<div class="overlay-backdrop copilot-backdrop" data-backdrop="true"><section class="copilot-drawer" role="dialog" aria-modal="true" aria-labelledby="copilot-title"><header class="copilot-head"><div class="between"><div class="flex">${icon('spark')}<h2 id="copilot-title">${t('সংগতিকে বলুন','Ask Shongoti')}</h2></div><button class="icon-button" data-action="close" aria-label="${t('বন্ধ করুন','Close')}">${icon('close')}</button></div><p>${t('Local demo · নমুনা হিসাবের উত্তর; live AI chat নয়।','Local demo · fixture-grounded answers, not live AI chat.')}</p></header><div class="copilot-messages" id="chat-messages">${messages}${state.chatBusy?`<div class="chat-message assistant" role="status"><span class="loading-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="sr-only">${t('Local উদাহরণের উত্তর তৈরি হচ্ছে','Preparing the local example answer')}</span></div>`:''}</div><form class="chat-composer" id="chat-form"><label for="chat-input">${t('প্রশ্ন লিখুন','Write your question')}</label><textarea id="chat-input" placeholder="${t('আজকের খরচ, পাওনা বা হিসাব…','Ask about spending, dues or evidence…')}" maxlength="1000" ${state.chatBusy?'disabled':''}>${escape(state.draftText)}</textarea><div class="between"><span class="meta muted">${t('কোনো message বাইরে পাঠানো হয় না।','No messages leave this preview.')}</span><button class="button primary compact" type="submit" ${state.chatBusy?'disabled':''}>${icon('send')}${t('জিজ্ঞেস করুন','Ask')}</button></div></form></section></div>`;
  if(!state.chatBusy)$('#chat-input').focus();
  $('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;
}
function sendChat(text) {
  if(state.chatBusy||!text.trim())return;
  state.chat.push({role:'user',text:text.trim()});state.draftText='';state.chatBusy=true;openCopilot();
  clearTimeout(chatTimer);chatTimer=setTimeout(()=>{
    let answer,action;const query=text.toLowerCase();
    if(/৮|8000|8,000|খরচ|spend|scenario/.test(query)){const r=scenario(800000,false);answer=t(`নমুনা হিসাব: হাতে ${money(AVAILABLE_PAISA)}। আজ ${money(800000)} খরচ করলে বৃহস্পতিবার projected balance ${money(r.values[3])}; রিজার্ভ ${money(RESERVE_PAISA)}। প্রতিশ্রুত টাকা actual funds-এ ধরা হয়নি।\nSource: synthetic 7-day baseline. এটি scenario, নিশ্চিত forecast নয়।`,`Example: ${money(AVAILABLE_PAISA)} is available. After spending ${money(800000)} today, Thursday projects to ${money(r.values[3])}, below the ${money(RESERVE_PAISA)} reserve. Promises are excluded from actual funds.\nSource: synthetic 7-day baseline. This is a scenario, not a guaranteed forecast.`);action='open-planner';}
    else if(/supplier|পাওনা|বিল|হিসাব|payment/.test(query)){const r=reconcile(state.paymentIncluded);answer=r.duePaisa===null?t('এখনই একটি নিশ্চিত অঙ্ক বলা যাবে না। ৪,০০০ টাকার payment বর্তমান দাবিতে আগেই বাদ থাকলে প্রদেয় ২২,০০০; এখনও বাদ না থাকলে ১৮,০০০।\nপ্রমাণের সমর্থন: ৫৯/১০০; একটি জরুরি তথ্য অজানা। Sources: INV-025, PAY-004, RETURN-003।','A final amount is not supported yet. Payable is ৳22,000 if the prior ৳4,000 payment is already reflected, or ৳18,000 if it is not.\nEvidence support: 59/100; one critical unknown. Sources: INV-025, PAY-004, RETURN-003.'):t(`নির্বাচিত উদাহরণের তথ্য অনুযায়ী প্রদেয় ${money(r.duePaisa)}। Support index 100/100 এই synthetic facts-এর জন্য; correctness probability নয়। Owner review এখনও প্রয়োজন।`,`Using the selected example facts, payable is ${money(r.duePaisa)}. Support index 100/100 covers those synthetic facts; it is not a correctness probability. Owner review is still required.`);action='open-case';}
    else if(/হাতে|balance|available|টাকা/.test(query)){answer=t(`নমুনা হিসাবে হাতে ${money(AVAILABLE_PAISA)}: নগদ ${money(500000)}, Nagad ${money(500000)}, bKash ${money(200000)}। পাওনা বা promise এতে যোগ হয়নি।\nSource: synthetic account snapshot, 9:41 AM.`,`The example has ${money(AVAILABLE_PAISA)} available: cash ${money(500000)}, Nagad ${money(500000)}, bKash ${money(200000)}. Receivables and promises are excluded.\nSource: synthetic account snapshot, 9:41 AM.`);action='open-dashboard';}
    else{answer=t('এই design preview-তে সাধারণ AI model যুক্ত নেই। হাতে থাকা টাকা, supplier-এর inclusion প্রশ্ন অথবা ৮,০০০ টাকার খরচের উদাহরণ জিজ্ঞেস করতে পারেন।','This design preview has no general AI model connected. Try the available-funds, supplier-inclusion or ৳8,000-spending examples.');}
    state.chat.push({role:'assistant',text:answer,action});state.chatBusy=false;if(overlayType==='copilot')openCopilot();
  },650);
}
function handleAction(action,el) {
  if(state.session?.kind==='merchant'&&!['logout','judge-login','language','motion','about','close','show-password'].includes(action)){toast(t('নিজের account-এ নমুনা হিসাব দেখানো হবে না। Judge workspace খুলে scenario দেখুন।','Sample finances are not shown as your records. Open the judge workspace to explore scenarios.'));return;}
  if(action==='close'){closeOverlay();return;}
  if(action.startsWith('open-')){if(action==='open-case')state.activeScenario='supplier';navigate(({ 'open-case':'case','open-planner':'planner','open-buying':'buying','open-dashboard':'dashboard','open-scenarios':'scenarios' })[action]||'dashboard');return;}
  switch(action){
    case 'judge-login':case 'reset-judge':enterJudge(el);break;
    case 'show-password':{const input=$('#auth-password');input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?t('দেখুন','Show'):t('লুকান','Hide');break;}
    case 'logout':if(state.authBusy)break;state.authBusy=true;authRequest('logout').then(()=>{clearTimeout(replayTimer);state.session=null;state.chat=[];state.replay=false;state.authError='';state.page='login';location.hash='/login';closeOverlay();render(true);}).catch(error=>toast(error.message)).finally(()=>state.authBusy=false);break;
    case 'work-filter':state.workFilter=el.dataset.filter;render();break;
    case 'scenario':{const selected=scenarios().find(s=>s.id===el.dataset.scenario);if(!selected)break;state.activeScenario=selected.id;if(selected.id==='cash'){state.expense=800000;state.promise=false;}if(selected.id==='offer')state.offer='shapla';navigate(selected.page);break;}
    case 'exception-review':{const selected=scenarios().find(s=>s.id===state.activeScenario);modal(t('ফল ও সীমা','Outcome and limits'),`<p class="dialog-intro">${escape(selected.title)}</p><div class="source-document"><p>${selected.id==='receiving'?t('Usable stock: ৭ বস্তা। সম্ভাব্য claim: ৩ বস্তা। Credit pending; payable-এ কোনো deduction নয়।','Usable stock: 7 bags. Potential claim: 3 bags. Credit pending; no deduction from payable.'):selected.id==='duplicate'?t('একটি payment reference, একটি প্রথম posting। দ্বিতীয় request blocked। এই UI example কোনো real payment পাঠায়নি।','One payment reference, one original posting. The second request is blocked. This UI example has sent no real payment.'):t('প্রযোজ্য deadline বা legal conclusion প্রতিষ্ঠিত নয়। আরও source যোগ করতে হবে।','No applicable deadline or legal conclusion is established. More source evidence is needed.')}</p><p>${t('এই ফল predefined fixture-এর। Production tool execution বা model inference-এর প্রমাণ নয়।','This outcome belongs to a predefined fixture, not proof of production tool execution or model inference.')}</p></div>${button('close',t('Review শেষ','Finish review'),'check','primary')}`);break;}
    case 'language': if('speechSynthesis'in window)speechSynthesis.cancel();closeOverlay();state.lang=state.lang==='bn'?'en':'bn';savePref('shongoti-design-language',state.lang);render();break;
    case 'motion': state.motion=state.motion==='on'?'off':'on';savePref('shongoti-design-motion',state.motion);render();toast(t('Motion preference বদলেছে।','Motion preference updated.'));break;
    case 'period':state.period=el.dataset.period;render();break;
    case 'chart-point':{const index=Number(el.dataset.index);if(el.dataset.kind==='flow'){state.selectedDay=index;const f=FLOW[state.period];$('#chart-readout').textContent=days()[index]+' · '+t('এসেছে','In')+' '+money(f.incoming[index])+' · '+t('গিয়েছে','Out')+' '+money(f.outgoing[index]);}else{const r=scenario(state.expense,state.promise);$('#runway-readout').textContent=days()[index]+' · Baseline '+money(BASELINE[index])+' · Scenario '+money(r.values[index]);}break;}
    case 'copilot':openCopilot();break;
    case 'chat-preset':sendChat(({scenario:t('আজ ৮,০০০ খরচ করলে কী হবে?','What if I spend 8000 today?'),case:t('Supplier-এর কত টাকা পাওনা?','How much do we owe the supplier?'),balance:t('হাতে কত টাকা আছে?','How much is available?')})[el.dataset.prompt]);break;
    case 'refresh':if(state.refreshing)break;state.refreshing=true;render();toast(t('নমুনা snapshot আবার দেখানো হচ্ছে; কোনো live fetch নয়।','Reloading the example snapshot; no live fetch.'));clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{state.refreshing=false;render();},650);break;
    case 'replay':if(!state.replay)startReplay();break;
    case 'pause-replay':state.paused=!state.paused;clearTimeout(replayTimer);render();if(!state.paused)nextReplay();break;
    case 'reset-case':clearTimeout(replayTimer);Object.assign(state,{paymentIncluded:null,step:4,replay:false,paused:false,events:[...REPLAY_STEPS],caseVersion:state.caseVersion+1});render();break;
    case 'answer':state.paymentIncluded=el.dataset.answer==='included'?true:el.dataset.answer==='not-included'?false:null;state.caseVersion+=1;render();toast(t('নমুনা clarification অনুযায়ী পুনরায় হিসাব হয়েছে। কোনো posting হয়নি।','Reassessed with your example clarification. Nothing was posted.'));break;
    case 'select-source':state.source=el.dataset.source;render();$('#evidence-trace').classList.add('flash');break;
    case 'source':showSource(el.dataset.source||'bill');break;
    case 'review-case':{const r=reconcile(state.paymentIncluded);if(r.duePaisa===null||state.replay)return;modal(t('খসড়া যাচাই করুন','Review the example draft'),`<p class="dialog-intro">${t('এই preview কোনো payment করে না।','This preview does not execute payments.')}</p><div class="source-document"><strong>CASE-024 · v${state.caseVersion}</strong><p>${t('প্রদেয়','Payable')}: <span class="money">${money(r.duePaisa)}</span></p><p>${t('Payment আগে বাদ আছে','Payment already reflected')}: ${state.paymentIncluded?t('হ্যাঁ','Yes'):t('না','No')}</p><p>${t('এই অঙ্কের উৎস: দাবি ২৫,০০০; গৃহীত ও আগে বাদ না দেওয়া ফেরত ৩,০০০; payment inclusion আপনার নির্বাচিত তথ্য।','Derived from demand ৳25,000, accepted return ৳3,000 not already included, and your selected payment-inclusion fact.')}</p></div>${button('close',t('খসড়া দেখা শেষ','Finish review'),'check','primary')}`);break;}
    case 'agent-detail':{const role=roles().find(r=>r.id===el.dataset.role)||roles()[0];modal(t(role.bn,role.en),`<p class="dialog-intro">${t('এটি specialist ভূমিকার visual concept। এই preview-তে আলাদা model inference চলছে না।','A visual concept for a specialist role. No separate model inference runs in this preview.')}</p><div class="source-document">${({coordinator:t('সমস্যাকে ছোট কাজ ও প্রয়োজনীয় প্রশ্নে ভাগ করে।','Divides the problem into bounded tasks and required questions.'),terms:t('মূল document-এর বক্তব্য, terms ও প্রমাণ খুঁজে দেয়।','Finds statements, terms and evidence in source documents.'),reconciliation:t('প্রতিষ্ঠিত facts দিয়ে exact deterministic calculation চালায়।','Uses established facts with an exact deterministic calculation tool.'),skeptic:t('অজানা তথ্য, বিরোধ বা double deduction-এর ঝুঁকি দেখায়।','Checks unknown facts, contradictions and double-deduction risks.')})[role.id]}</div>${button('close',t('বুঝেছি','Got it'),'check','primary')}`);break;}
    case 'quote-sources':modal(t('তিনটি নমুনা quotation','Three sample quotations'),`<p class="dialog-intro">${t('কোনো live supplier feed নয়। একই SKU, একই pack size।','Not a live supplier feed. Same SKU and pack size.')}</p><div class="source-document">${OFFERS.map(o=>`<p><strong>${o.ref} · ${t(o.bn,o.en)}</strong><br>${money(o.unitPaisa)} / ${t('বস্তা','bag')} + ${money(o.shippingPaisa)} ${t('delivery','delivery')}<br>${t(o.termBn,o.termEn)}</p>`).join('')}</div>`);break;
    case 'quote-source':{const o=OFFERS.find(o=>o.id===el.dataset.offer);modal(t(o.bn,o.en),`<p class="dialog-intro">${o.ref} · SYNTHETIC SOURCE</p><div class="source-document"><p>${t('২৫ কেজির বস্তা','25 kg bag')} · ${money(o.unitPaisa)}</p><p>${t('ডেলিভারি','Delivery')}: ${money(o.shippingPaisa)}</p><mark>${t(o.termBn,o.termEn)}</mark><p>${o.verified?t('এই নমুনায় লিখিত শর্ত ধরে খরচ দেখানো হয়েছে।','Costs use the recorded terms in this example.'):t('৬+১ অফারের যোগ্যতা প্রতিষ্ঠিত নয়। তাই free bag ধরে হিসাব হয়নি।','6+1 eligibility is not established. No free bag is assumed in the calculation.')}</p></div>`);break;}
    case 'buying-impact':state.expense=quoteTotal(state.offer,state.quantity);state.saved=false;navigate('planner');break;
    case 'draft-order':{const o=OFFERS.find(o=>o.id===state.offer);modal(t('Order-এর প্রস্তাবিত খসড়া','Proposed order draft'),`<p class="dialog-intro">${t('শুধু design review। Supplier-কে পাঠানো হয়নি; stock বা balance বদলায়নি।','For design review only. Not sent; stock and balances are unchanged.')}</p><div class="source-document"><strong>${t(o.bn,o.en)}</strong><p>${n(state.quantity)} × ${t('২৫ কেজি চাল','25 kg rice')}</p><p class="money">${money(quoteTotal(o.id,state.quantity))}</p><p>${t(o.termBn,o.termEn)}</p>${o.verified?'':`<p><mark>${t('Bonus-এর শর্ত আগে নিশ্চিত করুন।','Clarify the bonus condition first.')}</mark></p>`}</div>${button('close',t('Review শেষ','Finish review'),'check','primary')}`);break;}
    case 'reset-planner':state.expense=800000;state.promise=false;state.saved=false;render();break;
    case 'save-scenario':try{const parsed=parseMoneyPaisa($('#expense').value);if(parsed>20000000)throw new Error('range');}catch{toast(t('Invalid amount. Please correct the field.','Invalid amount. Please correct the field.'));break;}state.saved=true;render();toast(t('এই session-এ রাখা হয়েছে। Reload করলে থাকবে না; server save নয়।','Kept for this session. Reload clears it; this is not a server save.'));break;
    case 'scenario-facts':modal(t('Scenario-র সব শর্ত','Scenario assumptions'),`<p class="dialog-intro">${t('Deterministic illustration · evaluated forecast নয়।','Deterministic illustration · not an evaluated forecast.')}</p><div class="source-document"><p>${t('মূল baseline একটি synthetic ৭ দিনের account projection। Supplier payment ও অন্য net cashflow এতে আগে থেকেই ধরা আছে।','The baseline is a synthetic 7-day account projection, already including the supplier payment and other net cashflows.')}</p><p>${t('আজকের অতিরিক্ত খরচ প্রতিদিনের baseline থেকে একবার বাদ হয়। Promise চালু করলে বুধবার থেকে conditional alternative-এ ৪,০০০ টাকা যোগ হয়।','The additional spend is deducted once from each baseline day. Enabling the promise adds ৳4,000 to the conditional alternative from Wednesday.')}</p><p>${t('Actual available funds সবসময় ১২,০০০ টাকা থাকে। এই page ledger বদলায় না।','Actual available funds remain ৳12,000. This page does not mutate a ledger.')}</p></div>`);break;
    case 'speak':speakBrief();break;
    case 'inbox':modal(t('আজকের কাজের খবর','Today’s actionable inbox'),`<p class="dialog-intro">${t('নমুনা notification · সংশ্লিষ্ট কাজ খুলুন।','Sample notifications · open the related work.')}</p><div class="stack">${button('open-case',t('Supplier-এর inclusion প্রশ্নের উত্তর দিন','Answer the supplier inclusion question'),'help')}${button('open-planner',t('বৃহস্পতিবারের reserve দেখুন','Review Thursday’s reserve'),'graph')}${button('open-buying',t('চালের quotation তুলনা করুন','Compare rice quotations'),'bag')}</div>`);break;
    case 'search':modal(t('কোন কাজটি খুঁজছেন?','What would you like to find?'),`<p class="dialog-intro">${t('এই চারটি preview screen-এ যান।','Open one of the four preview screens.')}</p><div class="stack">${routes.map(r=>button('open-'+(r==='dashboard'?'dashboard':r==='case'?'case':r==='buying'?'buying':'planner'),pageNames()[r],['home','layers','bag','graph'][routes.indexOf(r)])).join('')}</div>`);break;
    case 'capture':modal(t('নতুন হিসাব যোগ করুন','Add a record'),`<p class="dialog-intro">${t('Capture-এর visual concept। এই preview-তে নতুন document upload বা posting করা হয় না।','Capture concept. This preview does not upload new documents or post transactions.')}</p><div class="stack">${button('source',t('নমুনা bill খুলুন','Open a sample bill'),'file','','data-source="bill"')}${button('open-case',t('নমুনা evidence review করুন','Review sample evidence'),'layers')}${button('copilot',t('প্রশ্ন লিখে শুরু করুন','Start with a question'),'spark')}</div>`);break;
    case 'records':modal(t('নমুনা লেনদেনের খাতা','Sample transaction journal'),`<p class="dialog-intro">${t('এগুলো design fixture; বর্তমান account snapshot-এর সম্পূর্ণ opening-to-closing ledger নয়।','These are design fixtures, not the complete opening-to-closing ledger behind the account snapshot.')}</p><div class="source-document"><p>S-028 · ${t('নগদ বিক্রি','Cash sale')} · ${money(125000)}</p><p>C-014 · ${t('আগের পাওনা আদায়','Prior due collection')} · ${money(80000)}</p><p>E-012 · ${t('খরচ','Expense')} · ${money(35000)}</p></div>`);break;
    case 'about':modal(t('আপনার feedback-এর জন্য','Made for your design review'),`<p class="dialog-intro">${t('চারটি screen, একটি product identity।','Four screens, one product identity.')}</p><div class="source-document"><p>${t('আপনার approved landing-এর paper, forest green, lime এবং Bangla-first visual language ধরে এই preview তৈরি।','This preview extends the approved landing’s paper, forest green, lime and Bangla-first visual language.')}</p><p>${t('সব টাকা, quotation, sources, agent ধাপ ও chat উত্তর synthetic। Real API, AI model, payment বা messaging যুক্ত নয়। মূল application অপরিবর্তিত।','All money, quotes, sources, agent steps and chat answers are synthetic. No real APIs, AI model, payments or messaging are connected. The main application is unchanged.')}</p></div>${quiet('motion',state.motion==='on'?t('Motion বন্ধ করুন','Turn motion off'):t('Motion চালু করুন','Turn motion on'),'settings')}`);break;
  }
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el);else if(event.target.matches('[data-backdrop]'))closeOverlay();});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&overlayType){closeOverlay();return;}
  if(overlayType&&event.key==='Tab'){const focusable=[...$('#overlay-root').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),textarea:not(:disabled),select,[tabindex="0"],summary')].filter(e=>!e.hidden);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  if((event.key==='Enter'||event.key===' ')&&event.target.matches('circle[data-action]')){event.preventDefault();handleAction(event.target.dataset.action,event.target);}
  if(event.key==='/'&&!overlayType&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){event.preventDefault();handleAction('search',document.body);}
});
document.addEventListener('input',event=>{
  const target=event.target;
  if(target.id==='chat-input')state.draftText=target.value;
  if(target.id==='expense-range'){state.expense=parseMoneyPaisa(target.value);state.saved=false;render();}
});
document.addEventListener('change',event=>{
  const target=event.target;
  if(target.name==='offer'){state.offer=target.value;render();}
  if(target.id==='quantity'){const quantity=Number(target.value);if(!Number.isInteger(quantity)||quantity<1||quantity>100){target.setCustomValidity(t('১ থেকে ১০০ পূর্ণসংখ্যা দিন।','Enter an integer from 1 to 100.'));target.reportValidity();target.value=state.quantity;target.setCustomValidity('');return;}state.quantity=quantity;render();}
  if(target.id==='expense'){try{const paisa=parseMoneyPaisa(target.value);if(paisa>20000000)throw new Error('range');state.expense=paisa;state.saved=false;render();}catch{$('#expense-error').textContent=t('০ থেকে ২,০০,০০০ টাকা দিন; সর্বোচ্চ ২ decimal place।','Enter 0–200,000 taka with at most two decimal places.');target.setAttribute('aria-invalid','true');}}
  if(target.id==='promise'){state.promise=target.checked;state.saved=false;render();}
});
document.addEventListener('submit',async event=>{
  if(event.target.id==='chat-form'){event.preventDefault();sendChat($('#chat-input').value);}
  if(event.target.id==='auth-form'){
    event.preventDefault();if(state.authBusy)return;const form=event.target,submit=form.querySelector('button[type="submit"]'),label=submit.innerHTML;
    const data=Object.fromEntries(new FormData(form));state.authBusy=true;submit.disabled=true;submit.innerHTML=`<span class="event-spinner"></span> ${t('যাচাই হচ্ছে…','Verifying…')}`;$('#auth-error').textContent='';
    try{const result=await authRequest(form.dataset.mode,data);state.session=result.user;state.authError='';state.page='dashboard';location.hash='/dashboard';render(true);}catch(error){$('#auth-error').textContent=error.message;submit.disabled=false;submit.innerHTML=label;}finally{state.authBusy=false;}
  }
});
window.addEventListener('hashchange',()=>{const next=routeFromHash();if(state.page!==next){state.page=next;closeOverlay();render(true);window.scrollTo({top:0,behavior:'instant'});($('#main')||$('#owner-name')||$('#auth-phone'))?.focus({preventScroll:true});}});
window.addEventListener('pagehide',()=>{clearTimeout(replayTimer);clearTimeout(chatTimer);clearTimeout(refreshTimer);if('speechSynthesis'in window)speechSynthesis.cancel();});
render(true);
bootstrap();
